<?php
require_once __DIR__ . '/lib/requests.php';
require_once __DIR__ . '/lib/flow_upgrade.php';
require_any_permission(['release_materials','confirm_receipt','resolve_receipt_discrepancies','view_requests']);
require_once __DIR__ . '/config/db.php';

$id = (int) ($_GET['id'] ?? 0);
$stmt = $pdo->prepare('SELECT rel.*, r.request_no, r.site_id, r.requested_by, s.name AS site_name, u.full_name AS released_by_name FROM material_releases rel JOIN material_requests r ON r.id = rel.request_id JOIN sites s ON s.id = r.site_id JOIN users u ON u.id = rel.released_by WHERE rel.id = ?');
$stmt->execute([$id]);
$release = $stmt->fetch();
if (!$release) { http_response_code(404); die('Release not found.'); }
require_site_engineer_record_access((int) $release['site_id'], (int) $release['requested_by']);
$itemsStmt = $pdo->prepare('SELECT ri.*, m.material_code, m.material_name, u.name AS unit_name FROM material_release_items ri JOIN materials m ON m.id = ri.material_id JOIN units u ON u.id = m.unit_id WHERE ri.release_id = ?');
$itemsStmt->execute([$id]);
$items = $itemsStmt->fetchAll();
$discrepancies = [];
if (db_table_exists($pdo, 'receipt_discrepancies')) {
    $d = $pdo->prepare('SELECT d.*,m.material_code,m.material_name,ru.full_name AS reporter_name,xu.full_name AS resolver_name FROM receipt_discrepancies d JOIN materials m ON m.id=d.material_id JOIN users ru ON ru.id=d.reported_by LEFT JOIN users xu ON xu.id=d.resolved_by WHERE d.release_id=? ORDER BY d.created_at DESC');
    $d->execute([$id]);
    $discrepancies = $d->fetchAll();
}
$activePage='requests'; $title='Release '.$release['release_no']; $eyebrow='MATERIAL RELEASE';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= e($title) ?></title><?php require __DIR__ . '/partials/assets.php'; ?></head><body><div class="app-layout"><?php require __DIR__ . '/partials/sidebar.php'; ?><main class="app-main"><?php require __DIR__ . '/partials/header.php'; ?><div class="page-content ops-document-page">
<section class="monitoring-top-card ops-document-summary"><div class="ops-document-identity"><span class="eyebrow light"><?= e($release['release_no']) ?></span><div><h2><?= e($release['request_no']) ?> to <?= e($release['site_name']) ?></h2><?= ui_status_badge((string)$release['status']) ?></div><p>Released by <?= e($release['released_by_name']) ?> on <?= e(date('M d, Y h:i A', strtotime($release['release_date']))) ?>.</p></div><dl class="ops-document-meta"><div><dt>Release no.</dt><dd><?= e($release['release_no']) ?></dd></div><div><dt>Request</dt><dd><?= e($release['request_no']) ?></dd></div><div><dt>Destination</dt><dd><?= e($release['site_name']) ?></dd></div><div><dt>Released to</dt><dd><?= e($release['released_to'] ?: 'Not specified') ?></dd></div></dl></section>
<div class="ops-sticky-actions ops-document-actions"><a class="btn secondary" href="request_view.php?id=<?= (int)$release['request_id'] ?>">Back to Request</a><a class="btn secondary" href="print_release.php?id=<?= (int)$id ?>" target="_blank" rel="noopener">Print Release</a><?php if(role_can((string)$_SESSION['role'],'manage_site_inventory')): ?><a class="btn secondary" href="site_inventory.php">Site Inventory</a><?php endif; ?></div>
<section class="form-card ops-section"><div class="ops-section-heading"><div><span class="eyebrow">Receipt</span><h2>Released Materials</h2><p>Confirmed quantities are added to the project-site stockroom. If less was received, choose a discrepancy reason.</p></div></div>
<form method="post" action="receipt_action.php" data-block-on-submit="Confirming receipt"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="release_id" value="<?= (int)$id ?>"><div class="ops-table-shell"><div class="table-wrap"><table class="data modern-table ops-table"><thead><tr><th>Material</th><th>Released</th><th>Received</th><th>Variance reason</th><th>Details</th></tr></thead><tbody><?php foreach($items as $item): $received=(float)$item['received_qty']; $default=$received>0?$received:(float)$item['released_qty']; ?><tr><td><b><?= e($item['material_code']) ?></b><small><?= e($item['material_name']) ?></small></td><td><?= money_or_qty($item['released_qty']) ?> <?= e($item['unit_name']) ?></td><td><input type="number" min="<?= e((string)$received) ?>" step="0.01" name="received_qty[<?= (int)$item['id'] ?>]" value="<?= e((string)$default) ?>" max="<?= e($item['released_qty']) ?>" <?= !role_can((string)$_SESSION['role'],'confirm_receipt')?'readonly':'' ?>></td><td><select name="discrepancy_reason[<?= (int)$item['id'] ?>]" <?= !role_can((string)$_SESSION['role'],'confirm_receipt')?'disabled':'' ?>><option value="short_delivery">Short delivery</option><option value="damaged_in_transit">Damaged in transit</option><option value="missing">Missing</option><option value="still_in_transit">Still in transit</option><option value="other">Other</option></select></td><td><input name="discrepancy_details[<?= (int)$item['id'] ?>]" placeholder="Optional details" <?= !role_can((string)$_SESSION['role'],'confirm_receipt')?'readonly':'' ?>></td></tr><?php endforeach; ?></tbody></table></div></div><?php if(role_can((string)$_SESSION['role'],'confirm_receipt')): ?><div class="form-actions ops-sticky-actions"><button class="btn primary" type="submit" data-confirm="Confirm the quantities received at the site?" data-confirm-title="Confirm receipt">Confirm Receipt</button></div><?php endif; ?></form></section>

<section class="content-card"><div class="card-heading"><div><span class="eyebrow">VARIANCES</span><h2>Receipt Discrepancies</h2><p>Any short receipt stays open until the warehouse manager records a resolution.</p></div></div><div class="table-wrap"><table class="data modern-table"><thead><tr><th>Material</th><th>Expected</th><th>Received</th><th>Variance</th><th>Reason</th><th>Status</th><th>Resolution</th></tr></thead><tbody><?php if(!$discrepancies): ?><tr><td colspan="7" class="muted">No receipt discrepancies recorded.</td></tr><?php endif; ?><?php foreach($discrepancies as $d): ?><tr><td><b><?= e($d['material_code']) ?></b><small><?= e($d['material_name']) ?></small></td><td><?= money_or_qty($d['expected_qty']) ?></td><td><?= money_or_qty($d['received_qty']) ?></td><td><?= money_or_qty($d['variance_qty']) ?></td><td><?= e(str_replace('_',' ',ucfirst($d['reason_code']))) ?><small><?= e($d['reason_details'] ?: '') ?></small></td><td><?= ui_status_badge((string)$d['status']) ?></td><td><?php if((string)$d['status']==='open' && role_can((string)$_SESSION['role'],'resolve_receipt_discrepancies')): ?><form method="post" action="discrepancy_action.php" class="inline-action-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="release_id" value="<?= (int)$id ?>"><input type="hidden" name="discrepancy_id" value="<?= (int)$d['id'] ?>"><select name="resolution"><option value="resolved_received">Later received</option><option value="resolved_returned">Returned / not due</option><option value="resolved_damage">Damage recorded</option><option value="resolved_writeoff">Authorized write-off</option></select><input name="remarks" placeholder="Resolution remarks" required><button class="btn secondary" type="submit">Resolve</button></form><?php else: ?><?= e($d['resolution_remarks'] ?: ($d['resolver_name'] ? 'Resolved by '.$d['resolver_name'] : '—')) ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
</div></main></div></body></html>
